1	//! Execution check evaluation.
2	//!
3	//! Runs a command and validates the result.
4	
5	use super::{truncate_display, CheckResult, ValidationMode};
6	use std::path::Path;
7	use std::process::Command;
8	
9	/// Evaluate an execution check.
10	///
11	/// Runs the command in a subprocess and validates the result according
12	/// to the validation mode:
13	/// - `Success`: command exits with code 0
14	/// - `Truthy`: command exits 0 AND produces non-empty stdout
15	/// - `Falsy`: command exits 0 AND produces empty stdout (or exits non-zero)
16	pub fn evaluate_execution(
17	    command: &str,
18	    validation: ValidationMode,
19	    project_root: &Path,
20	) -> CheckResult {
21	    let output = Command::new("sh")
22	        .arg("-c")
23	        .arg(command)
24	        .current_dir(project_root)
25	        .output();
26	
27	    let output = match output {
28	        Ok(o) => o,
29	        Err(e) => {
30	            return CheckResult::failed(
31	                format!(
32	                    "\u{2717} {} failed to execute",
33	                    truncate_display(command, 50)
34	                ),
35	                format!("Error: {}", e),
36	            );
37	        }
38	    };
39	
40	    let exit_success = output.status.success();
41	    let stdout = String::from_utf8_lossy(&output.stdout);
42	    let stdout_trimmed = stdout.trim();
43	
44	    match validation {
45	        ValidationMode::Success => {
46	            if exit_success {
47	                CheckResult::passed(format!(
48	                    "\u{2713} {} succeeded",
49	                    truncate_display(command, 50)
50	                ))
51	            } else {
52	                let code = output.status.code().unwrap_or(-1);
53	                CheckResult::failed(
54	                    format!(
55	                        "\u{2717} {} failed (exit code {})",
56	                        truncate_display(command, 50),
57	                        code
58	                    ),
59	                    "Exit code was non-zero",
60	                )
61	            }
62	        }
63	        ValidationMode::Truthy => {
64	            if exit_success && !stdout_trimmed.is_empty() {
65	                CheckResult::passed(format!(
66	                    "\u{2713} {} returned truthy output",
67	                    truncate_display(command, 50)
68	                ))
69	            } else if !exit_success {
70	                let code = output.status.code().unwrap_or(-1);
71	                CheckResult::failed(
72	                    format!(
73	                        "\u{2717} {} failed (exit code {})",
74	                        truncate_display(command, 50),
75	                        code
76	                    ),
77	                    "Command did not succeed",
78	                )
79	            } else {
80	                CheckResult::failed(
81	                    format!(
82	                        "\u{2717} {} returned empty output",
83	                        truncate_display(command, 50)
84	                    ),
85	                    "Command succeeded but produced no stdout",
86	                )
87	            }
88	        }
89	        ValidationMode::Falsy => {
90	            // Passes when: exits 0 with empty stdout, OR exits non-zero
91	            if !exit_success || stdout_trimmed.is_empty() {
92	                CheckResult::passed(format!(
93	                    "\u{2713} {} returned falsy",
94	                    truncate_display(command, 50)
95	                ))
96	            } else {
97	                CheckResult::failed(
98	                    format!(
99	                        "\u{2717} {} returned truthy output",
100	                        truncate_display(command, 50)
101	                    ),
102	                    format!(
103	                        "Expected empty output, got: {}",
104	                        truncate_display(stdout_trimmed, 100)
105	                    ),
106	                )
107	            }
108	        }
109	    }
110	}
