13	/// Aggregates all detection results.
14	#[derive(Debug)]
15	pub struct FullDetection {
16	    pub project: ProjectDetection,
17	    pub package_managers: PackageManagerDetection,
18	    pub conflicts: Vec<Conflict>,
19	    pub suggested_templates: Vec<SuggestedTemplate>,
20	}
21	
22	/// A suggested template from detection.
23	#[derive(Debug, Clone)]
24	pub struct SuggestedTemplate {
25	    pub name: TemplateName,
26	    pub category: String,
27	    pub reason: String,
28	    pub priority: u32,
29	}
30	
31	/// Runs all detectors and aggregates results.
32	pub struct DetectionRunner;
33	
34	impl DetectionRunner {
35	    /// Run all detectors on a project.
36	    pub fn run(project_root: &Path) -> FullDetection {
37	        let project = ProjectDetector::detect(project_root);
38	        let package_managers = PackageManagerDetector::detect(project_root);
39	        let conflicts = ConflictDetector::detect(project_root);
40	
41	        let suggested_templates = Self::suggest_templates(&project, &package_managers);
42	
43	        FullDetection {
44	            project,
45	            package_managers,
46	            conflicts,
47	            suggested_templates,
48	        }
49	    }
50	
51	    fn suggest_templates(
52	        project: &ProjectDetection,
53	        pm: &PackageManagerDetection,
54	    ) -> Vec<SuggestedTemplate> {
55	        let mut suggestions = Vec::new();
56	
57	        // System package manager (priority 10)
58	        if let Some(ref system_pm) = pm.system {
59	            let (name, category) = match system_pm {
60	                PackageManager::Homebrew => (TemplateName::BrewBundle, "system"),
61	                PackageManager::Chocolatey => (TemplateName::ChocoInstall, "windows"),
62	                PackageManager::Apt => (TemplateName::AptInstall, "system"),
63	                PackageManager::Yum => (TemplateName::YumInstall, "system"),
64	                PackageManager::Pacman => (TemplateName::PacmanInstall, "system"),
65	                _ => return suggestions,
66	            };
67	
68	            suggestions.push(SuggestedTemplate {
69	                name,
70	                category: category.to_string(),
71	                reason: "System package manager detected".to_string(),
72	                priority: 10,
73	            });
74	        }
75	
76	        // Version manager (priority 20)
77	        if let Some(ref vm) = pm.version_manager {
78	            let name = match vm {
79	                PackageManager::Mise => TemplateName::MiseTools,
80	                PackageManager::Asdf => TemplateName::AsdfTools,
81	                PackageManager::Volta => TemplateName::VoltaSetup,
82	                PackageManager::Fnm => TemplateName::FnmSetup,
83	                PackageManager::Nvm => TemplateName::NvmNode,
84	                PackageManager::Rbenv => TemplateName::RbenvRuby,
85	                PackageManager::Pyenv => TemplateName::PyenvPython,
86	                _ => return suggestions,
87	            };
88	
89	            suggestions.push(SuggestedTemplate {
90	                name,
91	                category: "version_manager".to_string(),
92	                reason: format!("{:?} detected", vm),
93	                priority: 20,
94	            });
95	        }
96	
97	        // Language templates from project detection (priority 30)
98	        for detail in &project.details {
99	            if let Some(template) = detail.suggested_template {
100	                suggestions.push(SuggestedTemplate {
101	                    name: template,
102	                    category: "language".to_string(),
103	                    reason: detail.details.first().cloned().unwrap_or_default(),
104	                    priority: 30,
105	                });
106	            }
107	        }
108	
109	        // Sort by priority
110	        suggestions.sort_by_key(|s| s.priority);
111	
112	        suggestions
113	    }
114	}
