1	//! Template resolution from multiple sources.
2	//!
3	//! Resolution order (first match wins):
4	//! 1. Project-local (.bivvy/templates/)
5	//! 2. User-local (~/.bivvy/templates/)
6	//! 3. Remote (by priority) - TODO in M11
7	//! 4. Built-in
8	
9	use crate::config::schema::TemplateSource as TemplateSourceConfig;
10	use crate::error::{BivvyError, Result};
11	use crate::registry::builtin::BuiltinLoader;
12	use crate::registry::local::LocalLoader;
13	use crate::registry::remote::RemoteLoader;
14	use crate::registry::template::{Template, TemplateSource};
15	use std::collections::HashMap;
16	use std::path::Path;
17	
18	/// A parsed template reference, optionally qualified by category.
19	///
20	/// Template references in config can use `category/name` syntax
21	/// (e.g., `rust/version-bump`) to disambiguate templates that share
22	/// a name across categories.
23	#[derive(Debug, Clone, PartialEq, Eq)]
24	struct TemplateRef<'a> {
25	    name: &'a str,
26	    category: Option<&'a str>,
27	}
28	
29	impl<'a> TemplateRef<'a> {
30	    /// Parse a template reference string.
31	    ///
32	    /// Supports two forms:
33	    /// - `"name"` — unqualified lookup (first match wins)
34	    /// - `"category/name"` — qualified lookup (must match both name and category)
35	    fn parse(input: &'a str) -> Self {
36	        match input.split_once('/') {
37	            Some((category, name)) if !category.is_empty() && !name.is_empty() => Self {
38	                name,
39	                category: Some(category),
40	            },
41	            _ => Self {
42	                name: input,
43	                category: None,
44	            },
45	        }
46	    }
47	}
