49	/// Template registry that resolves templates from multiple sources.
50	#[derive(Debug, Clone)]
51	pub struct Registry {
52	    builtin: BuiltinLoader,
53	    local: LocalLoader,
54	    remote: RemoteLoader,
55	}
56	
57	impl Registry {
58	    /// Create a new registry for a project (without remote sources).
59	    pub fn new(project_root: Option<&Path>) -> Result<Self> {
60	        Ok(Self {
61	            builtin: BuiltinLoader::new()?,
62	            local: LocalLoader::new(project_root)?,
63	            remote: RemoteLoader::empty(),
64	        })
65	    }
66	
67	    /// Create a registry with remote template sources.
68	    ///
69	    /// HTTP sources go through the shared template cache; Git sources are
70	    /// cloned (or updated) into a `git/` subdirectory of the cache root.
71	    /// Git source URLs are validated up front: only `https://`, `ssh://`,
72	    /// `git://`, and `git@` SCP-style URLs are accepted.
73	    pub fn with_remote_sources(
74	        project_root: Option<&Path>,
75	        sources: &[TemplateSourceConfig],
76	    ) -> Result<Self> {
77	        use crate::config::schema::TemplateSourceKind;
78	        use crate::registry::fetch::validate_git_url;
79	
80	        // Validate Git source URLs up front so the user gets a clear error
81	        // before we hit the network or filesystem.
82	        for source in sources {
83	            if source.effective_kind() == TemplateSourceKind::Git {
84	                validate_git_url(&source.url).map_err(|e| BivvyError::ConfigValidationError {
85	                    message: format!("Invalid git template source URL: {}", e),
86	                })?;
87	            }
88	        }
89	
90	        let http_fetcher = crate::registry::fetch::HttpFetcher::new();
91	        let cache_dir = crate::cache::default_cache_dir();
92	        let git_fetcher = crate::registry::fetch::GitFetcher::new(cache_dir.join("git"));
93	        let cache = crate::cache::CacheStore::new(cache_dir);
94	
95	        let remote =
96	            RemoteLoader::new(sources, &http_fetcher, &git_fetcher, &cache).map_err(|e| {
97	                BivvyError::ConfigValidationError {
98	                    message: format!("Failed to load remote templates: {}", e),
99	                }
100	            })?;
101	
102	        Ok(Self {
103	            builtin: BuiltinLoader::new()?,
104	            local: LocalLoader::new(project_root)?,
105	            remote,
106	        })
107	    }
108	
109	    /// Create a registry with a pre-loaded remote loader (for testing).
110	    #[cfg(test)]
111	    pub(crate) fn with_remote_loader(
112	        project_root: Option<&Path>,
113	        remote: RemoteLoader,
114	    ) -> Result<Self> {
115	        Ok(Self {
116	            builtin: BuiltinLoader::new()?,
117	            local: LocalLoader::new(project_root)?,
118	            remote,
119	        })
120	    }
121	
122	    /// Resolve a template by name, with optional `category/name` syntax.
123	    ///
124	    /// Template references can be:
125	    /// - `"name"` — unqualified lookup (first match wins)
126	    /// - `"category/name"` — qualified lookup (must match both name and category)
127	    ///
128	    /// Resolution order (first match wins):
129	    /// 1. Project-local (.bivvy/templates/)
130	    /// 2. User-local (~/.bivvy/templates/)
131	    /// 3. Remote (by priority)
132	    /// 4. Built-in
133	    pub fn resolve(&self, input: &str) -> Result<(&Template, TemplateSource)> {
134	        let tref = TemplateRef::parse(input);
135	
136	        // Check local first (includes both project and user)
137	        let local_result = match tref.category {
138	            Some(cat) => self.local.get_with_source_by_category(tref.name, cat),
139	            None => self.local.get_with_source(tref.name),
140	        };
141	        if let Some((template, source)) = local_result {
142	            return Ok((template, source));
143	        }
144	
145	        // Check remote sources
146	        let remote_result = match tref.category {
147	            Some(cat) => self.remote.get_with_priority_by_category(tref.name, cat),
148	            None => self.remote.get_with_priority(tref.name),
149	        };
150	        if let Some((template, priority)) = remote_result {
151	            return Ok((template, TemplateSource::Remote { priority }));
152	        }
153	
154	        // Check built-in
155	        let builtin_result = match tref.category {
156	            Some(cat) => self.builtin.get_by_category(tref.name, cat),
157	            None => self.builtin.get(tref.name),
158	        };
159	        if let Some(template) = builtin_result {
160	            return Ok((template, TemplateSource::Builtin));
161	        }
162	
163	        Err(BivvyError::UnknownTemplate {
164	            name: input.to_string(),
165	        })
166	    }
167	
168	    /// Get a template by name (without source info).
169	    ///
170	    /// Supports `category/name` syntax for qualified lookups.
171	    pub fn get(&self, input: &str) -> Option<&Template> {
172	        self.resolve(input).ok().map(|(t, _)| t)
173	    }
174	
175	    /// Check if a template exists.
176	    ///
177	    /// Supports `category/name` syntax for qualified lookups.
178	    pub fn has(&self, input: &str) -> bool {
179	        let tref = TemplateRef::parse(input);
180	        match tref.category {
181	            Some(cat) => {
182	                self.local
183	                    .get_with_source_by_category(tref.name, cat)
184	                    .is_some()
185	                    || self
186	                        .remote
187	                        .get_with_priority_by_category(tref.name, cat)
188	                        .is_some()
189	                    || self.builtin.get_by_category(tref.name, cat).is_some()
190	            }
191	            None => {
192	                self.local.has(tref.name)
193	                    || self.remote.has(tref.name)
194	                    || self.builtin.get(tref.name).is_some()
195	            }
196	        }
197	    }
198	
199	    /// Get all available template names.
200	    pub fn all_template_names(&self) -> Vec<String> {
201	        let mut names: Vec<String> = self
202	            .builtin
203	            .template_names()
204	            .into_iter()
205	            .map(|s| s.to_string())
206	            .collect();
207	
208	        // Add remote templates
209	        for name in self.remote.template_names() {
210	            if !names.contains(&name.to_string()) {
211	                names.push(name.to_string());
212	            }
213	        }
214	
215	        // Add local templates (may override both remote and built-in)
216	        for name in self.local.template_names() {
217	            if !names.contains(&name.to_string()) {
218	                names.push(name.to_string());
219	            }
220	        }
221	
222	        names.sort();
223	        names
224	    }
225	
226	    /// Get templates in detection order for `bivvy init`.
227	    pub fn detection_order(&self) -> Vec<&Template> {
228	        // Start with built-in detection order
229	        self.builtin.detection_order()
230	    }
231	
232	    /// Get the builtin loader (for manifest access).
233	    pub fn builtin(&self) -> &BuiltinLoader {
234	        &self.builtin
235	    }
236	
237	    /// Validate inputs against a template's input contract.
238	    pub fn validate_inputs(
239	        &self,
240	        template_name: &str,
241	        inputs: &HashMap<String, serde_yaml::Value>,
242	    ) -> Result<Vec<String>> {
243	        let template = self
244	            .get(template_name)
245	            .ok_or_else(|| BivvyError::UnknownTemplate {
246	                name: template_name.to_string(),
247	            })?;
248	
249	        let mut errors = Vec::new();
250	
251	        // Check all required inputs are provided
252	        for (name, contract) in &template.inputs {
253	            if let Err(e) = contract.validate(name, inputs.get(name)) {
254	                errors.push(e);
255	            }
256	        }
257	
258	        // Check no unknown inputs are provided
259	        for key in inputs.keys() {
260	            if !template.inputs.contains_key(key) {
261	                errors.push(format!(
262	                    "Unknown input '{}' for template '{}'",
263	                    key, template_name
264	                ));
265	            }
266	        }
267	
268	        Ok(errors)
269	    }
270	
271	    /// Get effective input values (provided + defaults).
272	    pub fn effective_inputs(
273	        &self,
274	        template_name: &str,
275	        provided: &HashMap<String, serde_yaml::Value>,
276	    ) -> Result<HashMap<String, serde_yaml::Value>> {
277	        let template = self
278	            .get(template_name)
279	            .ok_or_else(|| BivvyError::UnknownTemplate {
280	                name: template_name.to_string(),
281	            })?;
282	
283	        let mut effective = HashMap::new();
284	
285	        for (name, contract) in &template.inputs {
286	            if let Some(value) = contract.effective_value(provided.get(name)) {
287	                effective.insert(name.clone(), value.clone());
288	            }
289	        }
290	
291	        Ok(effective)
292	    }
293	}
