115	    /// Resolve steps from configuration.
116	    ///
117	    /// Steps with a `template` field are resolved through the Registry,
118	    /// which merges template defaults with config overrides. Steps without
119	    /// a template are treated as inline definitions.
120	    fn resolve_steps(
121	        &self,
122	        config: &crate::config::BivvyConfig,
123	        environment: Option<&str>,
124	    ) -> Result<HashMap<String, ResolvedStep>> {
125	        let registry = if config.template_sources.is_empty() {
126	            Registry::new(Some(&self.project_root))?
127	        } else {
128	            Registry::with_remote_sources(Some(&self.project_root), &config.template_sources)?
129	        };
130	
131	        let defaults = &config.settings.defaults;
132	        // Resolve the effective global rerun window: prefer defaults.rerun_window,
133	        // fall back to execution.default_rerun_window for backward compatibility.
134	        let global_rerun_window = defaults.rerun_window.as_deref().or(config
135	            .settings
136	            .execution
137	            .default_rerun_window
138	            .as_deref());
139	
140	        let mut steps = HashMap::new();
141	        for (name, step_config) in &config.steps {
142	            let mut resolved = if let Some(template_name) = &step_config.template {
143	                let (template, _source) = registry.resolve(template_name)?;
144	                ResolvedStep::from_template(
145	                    name,
146	                    template,
147	                    step_config,
148	                    &step_config.inputs,
149	                    environment,
150	                )
151	            } else {
152	                ResolvedStep::from_config(name, step_config, environment)
153	            };
154	
155	            // Apply global defaults for fields that weren't explicitly set at step level
156	            if step_config.behavior.auto_run.is_none() {
157	                resolved.behavior.auto_run = defaults.auto_run;
158	            }
159	            if step_config.behavior.prompt_on_rerun.is_none() {
160	                resolved.behavior.prompt_on_rerun = defaults.prompt_on_rerun;
161	            }
162	            if step_config.behavior.rerun_window.is_none() {
163	                if let Some(window_str) = global_rerun_window {
164	                    if let Ok(w) = window_str.parse() {
165	                        resolved.behavior.rerun_window = w;
166	                    }
167	                }
168	            }
169	
170	            steps.insert(name.clone(), resolved);
171	        }
172	        Ok(steps)
173	    }
174	}
