185	    let mut force: HashSet<String> = args.force.iter().cloned().collect();
186	    let mut force_all = args.force_all;
187	    if let Some(workflow) = workflow {
188	        force.extend(workflow.force.iter().cloned());
189	        force_all = force_all || workflow.force_all;
190	    }
191	    (force, force_all)
192	}
