1	//! Remote template loading from HTTP and Git sources.
2	//!
3	//! Fetches templates from URLs defined in `template_sources` and caches
4	//! them using the shared cache infrastructure (HTTP) or the on-disk clone
5	//! directory (Git).
6	
7	use anyhow::{Context, Result};
8	use std::collections::HashMap;
9	use std::fs;
10	use std::path::Path;
11	
12	use super::fetch::{GitFetcher, HttpFetcher};
13	use super::template::Template;
14	use crate::cache::{parse_ttl, CacheStore};
15	use crate::config::schema::{TemplateSource as TemplateSourceConfig, TemplateSourceKind};
16	
17	/// Loads templates from remote sources with caching.
18	#[derive(Debug, Clone)]
19	pub struct RemoteLoader {
20	    /// Fetched and parsed templates, keyed by `category/name`.
21	    templates: HashMap<String, (Template, u32)>,
22	}
23	
24	impl RemoteLoader {
25	    /// Create a new remote loader by fetching templates from the given sources.
26	    ///
27	    /// HTTP sources are fetched into the shared `CacheStore`; Git sources are
28	    /// cloned (or updated) into `git_fetcher`'s clone directory and their
29	    /// templates directory is walked for `*.yml`/`*.yaml` files.
30	    pub fn new(
31	        sources: &[TemplateSourceConfig],
32	        http_fetcher: &HttpFetcher,
33	        git_fetcher: &GitFetcher,
34	        cache: &CacheStore,
35	    ) -> Result<Self> {
36	        let mut templates = HashMap::new();
37	
38	        // Visit sources in priority order (lower `priority` number wins on
39	        // collision). Stable sort preserves declaration order among ties so
40	        // the user's listed-first source breaks the tie.
41	        let mut ordered: Vec<&TemplateSourceConfig> = sources.iter().collect();
42	        ordered.sort_by_key(|s| s.priority);
43	
44	        for source in ordered {
45	            let result = match source.effective_kind() {
46	                TemplateSourceKind::Http => Self::load_http_source(source, http_fetcher, cache),
47	                TemplateSourceKind::Git => Self::load_git_source(source, git_fetcher),
48	            };
49	
50	            match result {
51	                Ok(loaded) => {
52	                    for template in loaded {
53	                        // Higher-priority sources (lower number) win on collision.
54	                        let key = format!("{}/{}", template.category, template.name);
55	                        templates.entry(key).or_insert((template, source.priority));
56	                    }
57	                }
58	                Err(e) => {
59	                    tracing::warn!("Failed to load templates from {}: {}", source.url, e);
60	                }
61	            }
62	        }
63	
64	        Ok(Self { templates })
65	    }
66	
67	    /// Create an empty remote loader (no sources).
68	    pub fn empty() -> Self {
69	        Self {
70	            templates: HashMap::new(),
71	        }
72	    }
73	
74	    /// Load templates from a single HTTP source.
75	    fn load_http_source(
76	        source: &TemplateSourceConfig,
77	        fetcher: &HttpFetcher,
78	        cache: &CacheStore,
79	    ) -> Result<Vec<Template>> {
80	        let source_id = format!("http:{}", source.url);
81	
82	        // Check cache first
83	        if let Some(entry) = cache.load(&source_id, "_index")? {
84	            if !entry.is_expired() {
85	                let content = cache.read_content(&entry)?;
86	                return Self::parse_templates(&content);
87	            }
88	        }
89	
90	        // Fetch from remote
91	        let response = fetcher
92	            .fetch(&source.url)
93	            .with_context(|| format!("Failed to fetch template source: {}", source.url))?;
94	
95	        // Cache the response
96	        let ttl_seconds = source
97	            .cache
98	            .as_ref()
99	            .and_then(|c| parse_ttl(&c.ttl).ok())
100	            .map(|d| d.num_seconds() as u64)
101	            .unwrap_or(604800);
102	        cache.store(&source_id, "_index", &response.content, ttl_seconds)?;
103	
104	        Self::parse_templates(&response.content)
105	    }
106	
107	    /// Load templates from a single Git source.
108	    ///
109	    /// Clones (or updates) the repository, then walks `source.path` (or the
110	    /// repository root if `path` is unset) for `*.yml`/`*.yaml` files. Each
111	    /// file is parsed as a [`Template`]. Files that fail to parse are
112	    /// reported via `tracing::warn!` and skipped.
113	    ///
114	    /// URL scheme validation is the caller's responsibility: production code
115	    /// goes through [`Registry::with_remote_sources`](crate::registry::Registry::with_remote_sources),
116	    /// which validates each source up front.
117	    fn load_git_source(
118	        source: &TemplateSourceConfig,
119	        fetcher: &GitFetcher,
120	    ) -> Result<Vec<Template>> {
121	        let result = fetcher
122	            .fetch_unchecked(&source.url, source.git_ref.as_deref())
123	            .with_context(|| format!("Failed to clone git source: {}", source.url))?;
124	
125	        let walk_root = match &source.path {
126	            Some(sub) => result.local_path.join(sub),
127	            None => result.local_path.clone(),
128	        };
129	
130	        if !walk_root.exists() {
131	            anyhow::bail!(
132	                "Git source path does not exist: {} (in {})",
133	                source.path.as_deref().unwrap_or(""),
134	                source.url
135	            );
136	        }
137	
138	        let mut templates = Vec::new();
139	        Self::walk_templates(&walk_root, &mut templates);
140	        Ok(templates)
141	    }
142	
143	    /// Recursively walk `dir` collecting templates from `*.yml` / `*.yaml` files.
144	    /// Parse failures are logged and skipped so a single bad file does not
145	    /// abort the whole source.
146	    fn walk_templates(dir: &Path, out: &mut Vec<Template>) {
147	        let Ok(entries) = fs::read_dir(dir) else {
148	            return;
149	        };
150	
151	        for entry in entries.flatten() {
152	            let path = entry.path();
153	
154	            // Skip the .git directory and any other dotfiles.
155	            if path
156	                .file_name()
157	                .and_then(|n| n.to_str())
158	                .map(|n| n.starts_with('.'))
159	                .unwrap_or(false)
160	            {
161	                continue;
162	            }
163	
164	            if path.is_dir() {
165	                Self::walk_templates(&path, out);
166	                continue;
167	            }
168	
169	            let is_yaml = path
170	                .extension()
171	                .and_then(|e| e.to_str())
172	                .map(|e| e == "yml" || e == "yaml")
173	                .unwrap_or(false);
174	            if !is_yaml {
175	                continue;
176	            }
177	
178	            match fs::read_to_string(&path) {
179	                Ok(content) => match Self::parse_templates(&content) {
180	                    Ok(parsed) => out.extend(parsed),
181	                    Err(e) => {
182	                        tracing::warn!("Failed to parse template at {}: {}", path.display(), e);
183	                    }
184	                },
185	                Err(e) => {
186	                    tracing::warn!("Failed to read template at {}: {}", path.display(), e);
187	                }
188	            }
189	        }
190	    }
191	
192	    /// Parse a YAML string containing one or more templates.
193	    ///
194	    /// Supports two formats:
195	    /// 1. A single template YAML document
196	    /// 2. A YAML array of templates
197	    fn parse_templates(content: &str) -> Result<Vec<Template>> {
198	        // Try parsing as a list first
199	        if let Ok(templates) = serde_yaml::from_str::<Vec<Template>>(content) {
200	            return Ok(templates);
201	        }
202	
203	        // Try as a single template
204	        if let Ok(template) = serde_yaml::from_str::<Template>(content) {
205	            return Ok(vec![template]);
206	        }
207	
208	        anyhow::bail!(
209	            "Remote source returned content that is neither a template nor a list of templates"
210	        )
211	    }
212	
213	    /// Get a template by name (unqualified — returns first match).
214	    pub fn get(&self, name: &str) -> Option<&Template> {
215	        if let Some((t, _)) = self.templates.get(name) {
216	            return Some(t);
217	        }
218	        self.templates
219	            .values()
220	            .find(|(t, _)| t.name == name)
221	            .map(|(t, _)| t)
222	    }
223	
224	    /// Get a template with its priority (unqualified — returns first match).
225	    pub fn get_with_priority(&self, name: &str) -> Option<(&Template, u32)> {
226	        if let Some((t, p)) = self.templates.get(name) {
227	            return Some((t, *p));
228	        }
229	        self.templates
230	            .values()
231	            .find(|(t, _)| t.name == name)
232	            .map(|(t, p)| (t, *p))
233	    }
234	
235	    /// Get a template with its priority, filtering by category.
236	    pub fn get_with_priority_by_category(
237	        &self,
238	        name: &str,
239	        category: &str,
240	    ) -> Option<(&Template, u32)> {
241	        let key = format!("{}/{}", category, name);
242	        self.templates.get(&key).map(|(t, p)| (t, *p))
243	    }
244	
245	    /// Check if a template exists (by unqualified name).
