1	//! Persistent state storage.
2	//!
3	//! This module provides the main state storage for Bivvy projects,
4	//! tracking per-step execution state. Run history has moved to JSONL
5	//! event logs (see `src/logging/`).
6	
7	use chrono::{DateTime, Utc};
8	use serde::{Deserialize, Serialize};
9	use std::collections::HashMap;
10	use std::fs;
11	use std::path::PathBuf;
12	
13	use super::ProjectId;
14	
15	/// Persistent state for a project.
16	///
17	/// As of v3, run history (`runs`, `last_run`, `last_workflow`) has been
18	/// removed. Workflow execution history is now captured by the JSONL
19	/// event logger. The state store only tracks per-step execution state.
20	#[derive(Debug, Clone, Serialize, Deserialize)]
21	pub struct StateStore {
22	    /// Schema version for migration.
23	    pub version: u32,
24	
25	    /// Project identification.
26	    pub project: ProjectInfo,
27	
28	    /// State for each step.
29	    pub steps: HashMap<String, StepState>,
30	}
31	
32	/// Project information stored in state.
33	#[derive(Debug, Clone, Serialize, Deserialize)]
34	pub struct ProjectInfo {
35	    pub path: String,
36	    pub git_remote: Option<String>,
37	    pub name: String,
38	}
39	
40	/// State for a single step.
41	#[derive(Debug, Clone, Serialize, Deserialize)]
42	pub struct StepState {
43	    /// When this step last ran.
44	    pub last_run: Option<DateTime<Utc>>,
45	
46	    /// Status of the last run.
47	    pub status: StepStatus,
48	
49	    /// Duration of the last run in milliseconds.
50	    pub duration_ms: Option<u64>,
51	
52	    /// Legacy v1 watches hash. Present only in v1 state files that had
53	    /// change-detection watches configured. Consumed during migration to
54	    /// populate SnapshotStore baselines, then cleared.
55	    #[serde(default, skip_serializing_if = "Option::is_none")]
56	    pub watches_hash: Option<String>,
57	}
58	
59	/// A baseline migration entry extracted from v1 state.
60	///
61	/// Each entry represents a `watches_hash` from a v1 `StepState` that
62	/// should be recorded in the `SnapshotStore` as a `_last_run` baseline.
63	#[derive(Debug, Clone)]
64	pub struct BaselineMigration {
65	    /// Step name.
66	    pub step_name: String,
67	    /// The v1 watches hash to use as the initial baseline.
68	    pub hash: String,
69	}
70	
71	/// Status of a step execution.
72	#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
73	pub enum StepStatus {
74	    Success,
75	    Failed,
76	    Skipped,
77	    NeverRun,
78	}
79	
80	/// Summary for status command.
81	#[derive(Debug, Clone)]
82	pub struct StatusSummary {
83	    pub step_count: usize,
84	    pub complete_count: usize,
85	}
86	
87	impl StateStore {
88	    /// Current schema version.
89	    ///
90	    /// v3: Removed `runs`, `last_run`, `last_workflow` fields.
91	    ///     Run history is now in JSONL event logs.
92	    pub const CURRENT_VERSION: u32 = 3;
93	
94	    /// Create a new state store for a project.
95	    pub fn new(project_id: &ProjectId) -> Self {
96	        Self {
97	            version: Self::CURRENT_VERSION,
98	            project: ProjectInfo {
99	                path: project_id.path().to_string_lossy().to_string(),
100	                git_remote: project_id.git_remote().map(String::from),
101	                name: project_id.name().to_string(),
102	            },
103	            steps: HashMap::new(),
104	        }
105	    }
106	
107	    /// Get the state directory for a project.
108	    pub fn state_dir(project_id: &ProjectId) -> PathBuf {
109	        crate::sys::home_dir()
110	            .unwrap_or_else(|| PathBuf::from("~"))
111	            .join(".bivvy")
112	            .join("projects")
113	            .join(project_id.hash())
114	    }
115	
116	    /// Get the state file path.
117	    pub fn state_file(project_id: &ProjectId) -> PathBuf {
118	        Self::state_dir(project_id).join("state.yml")
119	    }
120	
121	    /// Load state from disk, applying migrations if needed.
122	    ///
123	    /// Returns the state store and any baseline migrations that need to be
124	    /// applied to the `SnapshotStore` (from v1 `watches_hash` fields).
125	    pub fn load(project_id: &ProjectId) -> crate::error::Result<(Self, Vec<BaselineMigration>)> {
126	        let path = Self::state_file(project_id);
127	
128	        if !path.exists() {
129	            return Ok((Self::new(project_id), Vec::new()));
130	        }
131	
132	        let content = fs::read_to_string(&path)?;
133	        let mut state: Self = serde_yaml::from_str(&content).map_err(|e| {
134	            crate::error::BivvyError::ConfigParseError {
135	                path: path.clone(),
136	                message: e.to_string(),
137	            }
138	        })?;
139	
140	        // Apply migrations
141	        let baselines = if state.version < Self::CURRENT_VERSION {
142	            state.migrate()
143	        } else {
144	            Vec::new()
145	        };
146	
147	        Ok((state, baselines))
148	    }
149	
150	    /// Apply any pending migrations to bring state to the current version.
151	    ///
152	    /// Returns baseline migrations extracted from v1 `watches_hash` fields.
153	    /// The caller should apply these to the `SnapshotStore`.
154	    fn migrate(&mut self) -> Vec<BaselineMigration> {
155	        let mut baselines = Vec::new();
156	
157	        // v1 → v2: Extract watches_hash from steps into baseline migrations
158	        if self.version < 2 {
159	            for (step_name, step_state) in &mut self.steps {
160	                if let Some(hash) = step_state.watches_hash.take() {
161	                    baselines.push(BaselineMigration {
162	                        step_name: step_name.clone(),
163	                        hash,
164	                    });
165	                }
166	            }
167	        }
168	
169	        // v2 → v3: Drop runs, last_run, last_workflow fields.
170	        // These fields are simply ignored during deserialization (they're
171	        // no longer in the struct). The migration just bumps the version
172	        // so the cleaned state is written on next save.
173	
174	        self.version = Self::CURRENT_VERSION;
175	        baselines
176	    }
177	
178	    /// Save state to disk using atomic write.
179	    ///
180	    /// Uses the write-to-temp-then-rename pattern to prevent corruption
181	    /// if the process crashes or loses power during the write operation.
182	    /// This ensures state files are never partially written.
183	    pub fn save(&self, project_id: &ProjectId) -> crate::error::Result<()> {
184	        let dir = Self::state_dir(project_id);
185	        fs::create_dir_all(&dir)?;
186	
187	        let path = Self::state_file(project_id);
188	        let content = serde_yaml::to_string(self).map_err(|e| {
189	            crate::error::BivvyError::ConfigValidationError {
190	                message: format!("Failed to serialize state: {}", e),
191	            }
192	        })?;
193	
194	        // Atomic write: write to temp file, then rename
195	        // This prevents corruption if process crashes mid-write
196	        let temp_path = path.with_extension("yml.tmp");
197	        fs::write(&temp_path, &content)?;
198	        fs::rename(&temp_path, &path)?;
199	
200	        Ok(())
201	    }
202	
203	    /// Get state for a step.
204	    pub fn get_step(&self, name: &str) -> Option<&StepState> {
205	        self.steps.get(name)
206	    }
207	
208	    /// Update state for a step.
209	    pub fn update_step(&mut self, name: &str, state: StepState) {
210	        self.steps.insert(name.to_string(), state);
211	    }
212	
213	    // --- Step State Tracking ---
214	
215	    /// Record a step execution result.
216	    pub fn record_step_result(
217	        &mut self,
218	        step: &str,
219	        status: StepStatus,
220	        duration: std::time::Duration,
221	    ) {
222	        let state = StepState {
223	            last_run: Some(Utc::now()),
224	            status,
225	            duration_ms: Some(duration.as_millis() as u64),
226	            watches_hash: None,
227	        };
228	        self.steps.insert(step.to_string(), state);
229	    }
230	
231	    /// Check if a step has been run successfully.
232	    pub fn is_step_complete(&self, step: &str) -> bool {
233	        self.steps
234	            .get(step)
235	            .map(|s| s.status == StepStatus::Success)
236	            .unwrap_or(false)
237	    }
238	
239	    /// Get the last run time for a step.
240	    pub fn step_last_run(&self, step: &str) -> Option<DateTime<Utc>> {
241	        self.steps.get(step).and_then(|s| s.last_run)
242	    }
243	
244	    /// Clear state for a specific step.
245	    pub fn clear_step(&mut self, step: &str) {
246	        self.steps.remove(step);
247	    }
248	
249	    /// Clear all step states.
250	    pub fn clear_all_steps(&mut self) {
251	        self.steps.clear();
252	    }
253	
254	    // --- Query Methods ---
255	
256	    /// Get a summary for the status command.
257	    pub fn status_summary(&self) -> StatusSummary {
258	        StatusSummary {
259	            step_count: self.steps.len(),
260	            complete_count: self
261	                .steps
262	                .values()
263	                .filter(|s| s.status == StepStatus::Success)
264	                .count(),
265	        }
266	    }
267	}
268	
269	impl Default for StepState {
270	    fn default() -> Self {
271	        Self {
272	            last_run: None,
273	            status: StepStatus::NeverRun,
274	            duration_ms: None,
275	            watches_hash: None,
276	        }
277	    }
278	}
