    }

    #[test]
    fn atomic_write_leaves_no_temp_files() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        store
            .store("http:test", "template1", "content", 3600)
            .unwrap();

        // No .tmp files should remain
        for entry in fs::read_dir(temp.path()).unwrap() {
            let path = entry.unwrap().path();
            assert!(
                path.extension().is_none_or(|e| e != "tmp"),
                "Temp file should not remain: {:?}",
                path
            );
        }
    }

    #[test]
    fn concurrent_stores_do_not_corrupt() {
        use std::sync::Arc;
        use std::thread;

        let temp = TempDir::new().unwrap();
        let root = temp.path().to_path_buf();

        let handles: Vec<_> = (0..8)
            .map(|i| {
                let root = root.clone();
                thread::spawn(move || {
                    let store = CacheStore::new(&root);
                    let content = format!("content-from-thread-{}", i);
                    store
                        .store("http:test", "shared-template", &content, 3600)
                        .unwrap();
                })
            })
            .collect();

        for h in handles {
            h.join().unwrap();
        }

        // After all threads complete, the cache should have a valid entry
        let store = CacheStore::new(&root);
        let entry = store.load("http:test", "shared-template").unwrap();
        assert!(entry.is_some(), "Entry must exist after concurrent stores");

        let entry = entry.unwrap();
        let content = store.read_content(&entry).unwrap();
        assert!(
            content.starts_with("content-from-thread-"),
            "Content should be from one of the threads, got: {}",
            content
        );
    }
